-- PRÁCTICA DE CAMPO 3 | PUESTO DE SALUD GRAN CHIMÚ (CASO ACADÉMICO)
-- SCRIPT 2 DE 2: DIMENSIONES, TABLAS DE HECHOS Y VISTAS PARA BI
-- SQL Server 2022 | Periodo de datos: 01/04/2026 al 30/09/2026.
--
-- REQUISITO: haber ejecutado antes el script de los 400 pacientes
--            (crea BI_GranChimu, dbo.Pacientes y dbo.vw_PacientesBI).
--
-- QUÉ AGREGA ESTE SCRIPT
--   Catálogos / dimensiones : DimFecha, DimGrupoEtario, DimSector, DimSeguro, DimServicio,
--                             DimTipoAtencion, DimEstadoCita, DimProfesional, DimDiagnostico.
--   Tablas transaccionales  : Citas, Atenciones, DiagnosticosAtencion (alimentan los hechos).
--   Vistas para BI          : vw_DimPaciente, vw_FactAtenciones, vw_FactDiagnosticos, vw_FactCitas
--                             + vw_SeguimientoCitas (uso operativo, con teléfono; NO va al cubo).
--   Cambios en dbo.Pacientes: columnas SectorID y SeguroID (claves foráneas a los catálogos).
--
-- IMPORTANTE: TODOS los datos son SINTÉTICOS (pacientes, profesionales, citas, diagnósticos).
-- Los diagnósticos usan códigos CIE-10 reales, pero su asignación a cada paciente es inventada.
-- Los feriados son referenciales: verificar en normas oficiales si el trabajo lo exige.
-- El script se puede volver a ejecutar: no duplica filas. Para recargar desde cero, ejecutar
-- primero el bloque opcional de reinicio (sección 1).

USE BI_GranChimu;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;   -- requerido por los índices filtrados
GO

-- 0. VERIFICACIÓN DE REQUISITOS.
IF OBJECT_ID(N'dbo.Pacientes', N'U') IS NULL OR OBJECT_ID(N'dbo.vw_PacientesBI', N'V') IS NULL
    THROW 51000, 'Primero ejecute el script de los 400 pacientes (dbo.Pacientes y dbo.vw_PacientesBI).', 1;
GO

-- 1. REINICIO OPCIONAL (descomentar solo si desea borrar y recargar hechos y catálogos).
/*
DROP VIEW IF EXISTS dbo.vw_SeguimientoCitas, dbo.vw_FactCitas, dbo.vw_FactDiagnosticos,
                    dbo.vw_FactAtenciones, dbo.vw_DimPaciente, dbo.vw_MapaPaciente;
DROP TABLE IF EXISTS dbo.DiagnosticosAtencion, dbo.Atenciones, dbo.Citas;
ALTER TABLE dbo.Pacientes DROP CONSTRAINT IF EXISTS FK_Pacientes_Sector, FK_Pacientes_Seguro;
DROP TABLE IF EXISTS dbo.DimProfesional, dbo.DimDiagnostico, dbo.DimEstadoCita, dbo.DimTipoAtencion,
                     dbo.DimServicio, dbo.DimSeguro, dbo.DimSector, dbo.DimGrupoEtario, dbo.DimFecha;
*/

-- 2. CATÁLOGOS Y DIMENSIONES.
IF OBJECT_ID(N'dbo.DimFecha', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimFecha
    (
        FechaKey        INT          NOT NULL,   -- formato AAAAMMDD
        Fecha           DATE         NOT NULL,
        Anio            SMALLINT     NOT NULL,
        Semestre        TINYINT      NOT NULL,
        Trimestre       TINYINT      NOT NULL,
        Mes             TINYINT      NOT NULL,
        NombreMes       NVARCHAR(12) NOT NULL,
        AnioMes         CHAR(7)      NOT NULL,   -- AAAA-MM
        SemanaISO       TINYINT      NOT NULL,
        DiaSemana       TINYINT      NOT NULL,   -- 1 = lunes ... 7 = domingo
        NombreDia       NVARCHAR(12) NOT NULL,
        EsFinDeSemana   BIT          NOT NULL,
        EsFeriado       BIT          NOT NULL,
        NombreFeriado   NVARCHAR(60) NULL,
        EsDiaLaborable  BIT          NOT NULL,   -- la posta atiende de lunes a sábado, salvo feriados
        CONSTRAINT PK_DimFecha PRIMARY KEY (FechaKey),
        CONSTRAINT UQ_DimFecha_Fecha UNIQUE (Fecha)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimGrupoEtario', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimGrupoEtario
    (
        GrupoEtarioID  TINYINT      NOT NULL,
        NombreGrupo    NVARCHAR(20) NOT NULL,
        EdadMinima     TINYINT      NOT NULL,
        EdadMaxima     TINYINT      NOT NULL,
        EtapaVida      NVARCHAR(20) NOT NULL,   -- etapas de vida del MINSA
        CONSTRAINT PK_DimGrupoEtario PRIMARY KEY (GrupoEtarioID),
        CONSTRAINT UQ_DimGrupoEtario_Nombre UNIQUE (NombreGrupo),
        CONSTRAINT CK_DimGrupoEtario_Rango CHECK (EdadMinima <= EdadMaxima)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimSector', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimSector
    (
        SectorID           TINYINT       NOT NULL,
        NombreSector       NVARCHAR(30)  NOT NULL,   -- coincide con Pacientes.SectorResidencia
        ZonaReferencial    NVARCHAR(40)  NOT NULL,
        PoblacionEstimada  INT           NOT NULL,   -- dato sintético
        Latitud            DECIMAL(9,6)  NULL,       -- completar con coordenadas reales si usará mapas
        Longitud           DECIMAL(9,6)  NULL,
        CONSTRAINT PK_DimSector PRIMARY KEY (SectorID),
        CONSTRAINT UQ_DimSector_Nombre UNIQUE (NombreSector),
        CONSTRAINT CK_DimSector_Poblacion CHECK (PoblacionEstimada > 0)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimSeguro', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimSeguro
    (
        SeguroID             TINYINT      NOT NULL,
        NombreSeguro         NVARCHAR(30) NOT NULL,   -- coincide con Pacientes.TipoSeguro
        TipoFinanciamiento   NVARCHAR(30) NOT NULL,
        CONSTRAINT PK_DimSeguro PRIMARY KEY (SeguroID),
        CONSTRAINT UQ_DimSeguro_Nombre UNIQUE (NombreSeguro)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimServicio', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimServicio
    (
        ServicioID      TINYINT      NOT NULL,
        NombreServicio  NVARCHAR(30) NOT NULL,
        AreaFuncional   NVARCHAR(40) NOT NULL,
        CONSTRAINT PK_DimServicio PRIMARY KEY (ServicioID),
        CONSTRAINT UQ_DimServicio_Nombre UNIQUE (NombreServicio)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimTipoAtencion', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimTipoAtencion
    (
        TipoAtencionID  TINYINT      NOT NULL,
        NombreTipo      NVARCHAR(30) NOT NULL,
        CONSTRAINT PK_DimTipoAtencion PRIMARY KEY (TipoAtencionID),
        CONSTRAINT UQ_DimTipoAtencion_Nombre UNIQUE (NombreTipo)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimEstadoCita', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimEstadoCita
    (
        EstadoCitaID  TINYINT       NOT NULL,
        NombreEstado  NVARCHAR(20)  NOT NULL,
        Descripcion   NVARCHAR(100) NOT NULL,
        CONSTRAINT PK_DimEstadoCita PRIMARY KEY (EstadoCitaID),
        CONSTRAINT UQ_DimEstadoCita_Nombre UNIQUE (NombreEstado)
    );
END;
GO

IF OBJECT_ID(N'dbo.DimProfesional', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimProfesional
    (
        ProfesionalID    SMALLINT      NOT NULL,
        NombreCompleto   NVARCHAR(100) NOT NULL,   -- nombres inventados
        Profesion        NVARCHAR(40)  NOT NULL,
        ServicioID       TINYINT       NOT NULL,
        CondicionLaboral NVARCHAR(20)  NOT NULL,
        Activo           BIT           NOT NULL CONSTRAINT DF_DimProfesional_Activo DEFAULT (1),
        CONSTRAINT PK_DimProfesional PRIMARY KEY (ProfesionalID),
        CONSTRAINT UQ_DimProfesional_Servicio UNIQUE (ProfesionalID, ServicioID),   -- destino de la FK compuesta
        CONSTRAINT FK_DimProfesional_Servicio FOREIGN KEY (ServicioID) REFERENCES dbo.DimServicio (ServicioID),
        CONSTRAINT CK_DimProfesional_Condicion CHECK (CondicionLaboral IN (N'Nombrado', N'CAS', N'SERUMS', N'Terceros'))
    );
END;
GO

IF OBJECT_ID(N'dbo.DimDiagnostico', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DimDiagnostico
    (
        DiagnosticoID  SMALLINT      NOT NULL,
        CodigoCIE10    VARCHAR(8)    NOT NULL,
        Descripcion    NVARCHAR(150) NOT NULL,
        CapituloCIE10  NVARCHAR(120) NOT NULL,
        GrupoClinico   NVARCHAR(60)  NOT NULL,   -- agrupación propia del proyecto para tableros
        EsCronico      BIT           NOT NULL,
        CONSTRAINT PK_DimDiagnostico PRIMARY KEY (DiagnosticoID),
        CONSTRAINT UQ_DimDiagnostico_Codigo UNIQUE (CodigoCIE10)
    );
END;
GO

