INSERT INTO dbo.DimGrupoEtario
    (GrupoEtarioID, NombreGrupo, EdadMinima, EdadMaxima, EtapaVida)
SELECT v.GrupoEtarioID, v.NombreGrupo, v.EdadMinima, v.EdadMaxima, v.EtapaVida
FROM (VALUES
    (1, N'00-05 años', 0, 5, N'Niño'),
    (2, N'06-11 años', 6, 11, N'Niño'),
    (3, N'12-17 años', 12, 17, N'Adolescente'),
    (4, N'18-29 años', 18, 29, N'Joven'),
    (5, N'30-59 años', 30, 59, N'Adulto'),
    (6, N'60+ años', 60, 120, N'Adulto mayor')
) AS v(GrupoEtarioID, NombreGrupo, EdadMinima, EdadMaxima, EtapaVida)
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.DimGrupoEtario AS t WHERE t.GrupoEtarioID = v.GrupoEtarioID
);
GO

-- Población estimada por sector: dato SINTÉTICO.
INSERT INTO dbo.DimSector
    (SectorID, NombreSector, ZonaReferencial, PoblacionEstimada)
SELECT v.SectorID, v.NombreSector, v.ZonaReferencial, v.PoblacionEstimada
FROM (VALUES
    (1, N'Sector 01', N'Zona urbana central', 1200),
    (2, N'Sector 02', N'Zona urbana periférica', 1050),
    (3, N'Sector 03', N'Zona de expansión', 950),
    (4, N'Sector 04', N'Zona rural cercana', 1100),
    (5, N'Sector 05', N'Zona rural alejada', 900)
) AS v(SectorID, NombreSector, ZonaReferencial, PoblacionEstimada)
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.DimSector AS t WHERE t.SectorID = v.SectorID
);
GO

INSERT INTO dbo.DimSeguro
