INSERT INTO dbo.DimEstadoCita
    (EstadoCitaID, NombreEstado, Descripcion)
SELECT v.EstadoCitaID, v.NombreEstado, v.Descripcion
FROM (VALUES
    (1, N'Programada', N'Cita registrada, aún no llega la fecha'),
    (2, N'Asistió', N'El paciente acudió y fue atendido'),
    (3, N'No asistió', N'El paciente no acudió a la fecha programada'),
    (4, N'Reprogramada', N'Se cambió la fecha; genera una nueva cita'),
    (5, N'Cancelada', N'Cita anulada por el paciente o por el establecimiento')
) AS v(EstadoCitaID, NombreEstado, Descripcion)
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.DimEstadoCita AS t WHERE t.EstadoCitaID = v.EstadoCitaID
);
GO

