-- 3. RELACIONAR dbo.Pacientes CON LOS CATÁLOGOS (se conservan SectorResidencia y TipoSeguro).
IF COL_LENGTH(N'dbo.Pacientes', N'SectorID') IS NULL
    ALTER TABLE dbo.Pacientes ADD SectorID TINYINT NULL;
IF COL_LENGTH(N'dbo.Pacientes', N'SeguroID') IS NULL
    ALTER TABLE dbo.Pacientes ADD SeguroID TINYINT NULL;
GO

UPDATE p SET p.SectorID = s.SectorID
FROM dbo.Pacientes AS p JOIN dbo.DimSector AS s ON s.NombreSector = p.SectorResidencia
WHERE p.SectorID IS NULL;

UPDATE p SET p.SeguroID = s.SeguroID
FROM dbo.Pacientes AS p JOIN dbo.DimSeguro AS s ON s.NombreSeguro = p.TipoSeguro
WHERE p.SeguroID IS NULL;
GO

IF EXISTS (SELECT 1 FROM dbo.Pacientes WHERE SectorID IS NULL OR SeguroID IS NULL)
    THROW 51001, 'Hay pacientes cuyo sector o seguro no existe en los catálogos.', 1;
GO

IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Pacientes') AND name = N'SectorID' AND is_nullable = 1)
    ALTER TABLE dbo.Pacientes ALTER COLUMN SectorID TINYINT NOT NULL;
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Pacientes') AND name = N'SeguroID' AND is_nullable = 1)
    ALTER TABLE dbo.Pacientes ALTER COLUMN SeguroID TINYINT NOT NULL;
GO

IF NOT EXISTS (SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_Pacientes_Sector')
    ALTER TABLE dbo.Pacientes ADD CONSTRAINT FK_Pacientes_Sector
        FOREIGN KEY (SectorID) REFERENCES dbo.DimSector (SectorID);
IF NOT EXISTS (SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_Pacientes_Seguro')
    ALTER TABLE dbo.Pacientes ADD CONSTRAINT FK_Pacientes_Seguro
        FOREIGN KEY (SeguroID) REFERENCES dbo.DimSeguro (SeguroID);
GO

-- 4. TABLAS TRANSACCIONALES.
-- Citas: programación y resultado (asistió, no asistió, reprogramada, cancelada).
-- NumeroCita: 2 = segunda cita (primer seguimiento tras la atención inicial sin cita), 3 = tercera, etc.
-- Una cita reprogramada o retomada tras inasistencia conserva su NumeroCita y apunta a la anterior.
IF OBJECT_ID(N'dbo.Citas', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.Citas
    (
        CitaID               INT           NOT NULL,
        DNI                  CHAR(8)       NOT NULL,
        ServicioID           TINYINT       NOT NULL,
        ProfesionalID        SMALLINT      NOT NULL,
        FechaRegistroCita    DATE          NOT NULL,
        FechaProgramada      DATE          NOT NULL,
        EstadoCitaID         TINYINT       NOT NULL,
        NumeroCita           TINYINT       NOT NULL,
        MotivoCita           NVARCHAR(40)  NOT NULL,
        CitaAnteriorID       INT           NULL,
        RecordatorioEnviado  BIT           NOT NULL,
        MedioRecordatorio    NVARCHAR(15)  NULL,
        CONSTRAINT PK_Citas PRIMARY KEY (CitaID),
        CONSTRAINT FK_Citas_Paciente    FOREIGN KEY (DNI)            REFERENCES dbo.Pacientes (DNI),
        CONSTRAINT FK_Citas_Servicio    FOREIGN KEY (ServicioID)     REFERENCES dbo.DimServicio (ServicioID),
        CONSTRAINT FK_Citas_ProfServicio FOREIGN KEY (ProfesionalID, ServicioID)
                                                      REFERENCES dbo.DimProfesional (ProfesionalID, ServicioID),
        CONSTRAINT FK_Citas_Estado      FOREIGN KEY (EstadoCitaID)   REFERENCES dbo.DimEstadoCita (EstadoCitaID),
        CONSTRAINT FK_Citas_FechaReg    FOREIGN KEY (FechaRegistroCita) REFERENCES dbo.DimFecha (Fecha),
        CONSTRAINT FK_Citas_FechaProg   FOREIGN KEY (FechaProgramada)   REFERENCES dbo.DimFecha (Fecha),
        CONSTRAINT FK_Citas_Anterior    FOREIGN KEY (CitaAnteriorID) REFERENCES dbo.Citas (CitaID),
        CONSTRAINT CK_Citas_Fechas      CHECK (FechaProgramada >= FechaRegistroCita),
        CONSTRAINT CK_Citas_Numero      CHECK (NumeroCita >= 2),
        CONSTRAINT CK_Citas_Recordatorio CHECK ((RecordatorioEnviado = 1 AND MedioRecordatorio IS NOT NULL)
                                             OR (RecordatorioEnviado = 0 AND MedioRecordatorio IS NULL)),
        CONSTRAINT CK_Citas_Medio       CHECK (MedioRecordatorio IS NULL OR MedioRecordatorio IN (N'Llamada', N'WhatsApp', N'SMS'))
    );
END;
GO

-- Atenciones: cada contacto efectivo del paciente con un servicio (hecho principal).
-- CitaID es NULL cuando el paciente llegó sin cita previa.
IF OBJECT_ID(N'dbo.Atenciones', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.Atenciones
    (
        AtencionID       INT          NOT NULL,
        DNI              CHAR(8)      NOT NULL,
        FechaAtencion    DATE         NOT NULL,
        HoraInicio       TIME(0)      NOT NULL,
        ServicioID       TINYINT      NOT NULL,
        ProfesionalID    SMALLINT     NOT NULL,
        TipoAtencionID   TINYINT      NOT NULL,
        CitaID           INT          NULL,
        EdadAnios        TINYINT      NOT NULL,   -- edad cumplida a la fecha de la atención
        TiempoEsperaMin  SMALLINT     NOT NULL,
        DuracionMin      SMALLINT     NOT NULL,
        CONSTRAINT PK_Atenciones PRIMARY KEY (AtencionID),
        CONSTRAINT FK_Atenciones_Paciente    FOREIGN KEY (DNI)            REFERENCES dbo.Pacientes (DNI),
        CONSTRAINT FK_Atenciones_Fecha       FOREIGN KEY (FechaAtencion)  REFERENCES dbo.DimFecha (Fecha),
        CONSTRAINT FK_Atenciones_Servicio    FOREIGN KEY (ServicioID)     REFERENCES dbo.DimServicio (ServicioID),
        CONSTRAINT FK_Atenciones_ProfServicio FOREIGN KEY (ProfesionalID, ServicioID)
                                                      REFERENCES dbo.DimProfesional (ProfesionalID, ServicioID),
        CONSTRAINT FK_Atenciones_Tipo        FOREIGN KEY (TipoAtencionID) REFERENCES dbo.DimTipoAtencion (TipoAtencionID),
        CONSTRAINT FK_Atenciones_Cita        FOREIGN KEY (CitaID)         REFERENCES dbo.Citas (CitaID),
        CONSTRAINT CK_Atenciones_Edad        CHECK (EdadAnios <= 120),
        CONSTRAINT CK_Atenciones_Espera      CHECK (TiempoEsperaMin >= 0),
        CONSTRAINT CK_Atenciones_Duracion    CHECK (DuracionMin > 0)
    );
END;
GO

-- Diagnósticos por atención (una atención puede tener de 1 a 3).
-- TipoDx sigue la lógica del HIS: P = presuntivo, D = definitivo, R = repetido.
IF OBJECT_ID(N'dbo.DiagnosticosAtencion', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DiagnosticosAtencion
    (
        AtencionID     INT         NOT NULL,
        Orden          TINYINT     NOT NULL,   -- 1 = diagnóstico principal
        DiagnosticoID  SMALLINT    NOT NULL,
        TipoDx         CHAR(1)     NOT NULL,
        CONSTRAINT PK_DiagnosticosAtencion PRIMARY KEY (AtencionID, Orden),
        CONSTRAINT FK_DxAtencion_Atencion    FOREIGN KEY (AtencionID)    REFERENCES dbo.Atenciones (AtencionID),
        CONSTRAINT FK_DxAtencion_Diagnostico FOREIGN KEY (DiagnosticoID) REFERENCES dbo.DimDiagnostico (DiagnosticoID),
        CONSTRAINT CK_DxAtencion_Tipo  CHECK (TipoDx IN ('P', 'D', 'R')),
        CONSTRAINT CK_DxAtencion_Orden CHECK (Orden BETWEEN 1 AND 3)
    );
END;
GO

-- Índices de apoyo a las consultas y a la carga del cubo.
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Citas_DNI' AND object_id = OBJECT_ID(N'dbo.Citas'))
    CREATE INDEX IX_Citas_DNI ON dbo.Citas (DNI, FechaProgramada);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Citas_Anterior' AND object_id = OBJECT_ID(N'dbo.Citas'))
    CREATE UNIQUE INDEX UX_Citas_Anterior ON dbo.Citas (CitaAnteriorID) WHERE CitaAnteriorID IS NOT NULL;   -- una cita tiene a lo sumo una sucesora
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Atenciones_DNI' AND object_id = OBJECT_ID(N'dbo.Atenciones'))
    CREATE INDEX IX_Atenciones_DNI ON dbo.Atenciones (DNI, FechaAtencion);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Atenciones_Fecha' AND object_id = OBJECT_ID(N'dbo.Atenciones'))
    CREATE INDEX IX_Atenciones_Fecha ON dbo.Atenciones (FechaAtencion, ServicioID);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Atenciones_Paciente_Servicio_Dia' AND object_id = OBJECT_ID(N'dbo.Atenciones'))
    CREATE UNIQUE INDEX UX_Atenciones_Paciente_Servicio_Dia ON dbo.Atenciones (DNI, ServicioID, FechaAtencion);   -- una atención por servicio y día
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Atenciones_Cita' AND object_id = OBJECT_ID(N'dbo.Atenciones'))
    CREATE UNIQUE INDEX UX_Atenciones_Cita ON dbo.Atenciones (CitaID) WHERE CitaID IS NOT NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_DxAtencion_Dx' AND object_id = OBJECT_ID(N'dbo.DiagnosticosAtencion'))
    CREATE INDEX IX_DxAtencion_Dx ON dbo.DiagnosticosAtencion (DiagnosticoID);
GO

