-- 5. VISTAS PARA BI (SSAS / Power BI).
-- vw_MapaPaciente: SOLO uso interno. Asigna una clave sustituta entera a cada DNI.
-- No se importa al modelo: así el DNI no viaja a Power BI ni al cubo.
CREATE OR ALTER VIEW dbo.vw_MapaPaciente
AS
SELECT p.DNI, CAST(ROW_NUMBER() OVER (ORDER BY p.DNI) AS INT) AS PacienteKey
FROM dbo.Pacientes AS p;
GO

-- Dimensión Paciente: sin DNI, nombres ni teléfono (datos personales fuera del modelo analítico).
CREATE OR ALTER VIEW dbo.vw_DimPaciente
AS
SELECT
    m.PacienteKey,
    p.CodigoPaciente,
    p.Sexo,
    p.FechaNacimiento,
    b.EdadAlCierre,
    g.GrupoEtarioID,
    g.NombreGrupo        AS GrupoEtario,
    g.EtapaVida,
    s.SectorID,
    s.NombreSector,
    s.ZonaReferencial,
    sg.SeguroID,
    sg.NombreSeguro,
    sg.TipoFinanciamiento,
    p.FechaRegistro,
    LEFT(CONVERT(CHAR(10), p.FechaRegistro, 23), 7) AS AnioMesRegistro
FROM dbo.Pacientes AS p
JOIN dbo.vw_MapaPaciente AS m ON m.DNI = p.DNI
JOIN dbo.vw_PacientesBI  AS b ON b.DNI = p.DNI
JOIN dbo.DimGrupoEtario  AS g ON b.EdadAlCierre BETWEEN g.EdadMinima AND g.EdadMaxima
JOIN dbo.DimSector       AS s ON s.SectorID = p.SectorID
JOIN dbo.DimSeguro       AS sg ON sg.SeguroID = p.SeguroID;
GO

-- Hecho 1: una fila por atención. Medidas: CantidadAtenciones, TiempoEsperaMin, DuracionMin.
CREATE OR ALTER VIEW dbo.vw_FactAtenciones
AS
SELECT
    a.AtencionID                                              AS AtencionKey,
    CONVERT(INT, CONVERT(CHAR(8), a.FechaAtencion, 112))      AS FechaKey,
    m.PacienteKey,
    a.ServicioID,
    a.ProfesionalID,
    a.TipoAtencionID,
    g.GrupoEtarioID,                                          -- grupo etario a la fecha de la atención
    a.EdadAnios,
    a.HoraInicio,
    CASE WHEN a.HoraInicio < CAST('14:00' AS TIME) THEN N'Mañana' ELSE N'Tarde' END AS Turno,
    a.TiempoEsperaMin,
    a.DuracionMin,
    CASE WHEN a.CitaID IS NULL THEN 0 ELSE 1 END              AS EsConCita,
    1                                                         AS CantidadAtenciones
FROM dbo.Atenciones AS a
JOIN dbo.vw_MapaPaciente AS m ON m.DNI = a.DNI
JOIN dbo.DimGrupoEtario  AS g ON a.EdadAnios BETWEEN g.EdadMinima AND g.EdadMaxima;
GO

-- Hecho 2: una fila por diagnóstico registrado. Medida: CantidadDiagnosticos.
CREATE OR ALTER VIEW dbo.vw_FactDiagnosticos
AS
SELECT
    d.AtencionID                                              AS AtencionKey,
    d.Orden,
    CONVERT(INT, CONVERT(CHAR(8), a.FechaAtencion, 112))      AS FechaKey,
    m.PacienteKey,
    a.ServicioID,
    d.DiagnosticoID,
    d.TipoDx,
    g.GrupoEtarioID,
    CASE WHEN d.Orden = 1 THEN 1 ELSE 0 END                   AS EsDiagnosticoPrincipal,
    1                                                         AS CantidadDiagnosticos
FROM dbo.DiagnosticosAtencion AS d
JOIN dbo.Atenciones      AS a ON a.AtencionID = d.AtencionID
JOIN dbo.vw_MapaPaciente AS m ON m.DNI = a.DNI
JOIN dbo.DimGrupoEtario  AS g ON a.EdadAnios BETWEEN g.EdadMinima AND g.EdadMaxima;
GO

-- Hecho 3: una fila por cita. Medidas: CantidadCitas, Asistidas, Inasistencias, DiasAnticipacion.
CREATE OR ALTER VIEW dbo.vw_FactCitas
AS
SELECT
    c.CitaID                                                  AS CitaKey,
    CONVERT(INT, CONVERT(CHAR(8), c.FechaProgramada, 112))    AS FechaProgramadaKey,
    CONVERT(INT, CONVERT(CHAR(8), c.FechaRegistroCita, 112))  AS FechaRegistroKey,
    m.PacienteKey,
    c.ServicioID,
    c.ProfesionalID,
    c.EstadoCitaID,
    c.NumeroCita,
    c.MotivoCita,
    c.RecordatorioEnviado,
    c.MedioRecordatorio,
    DATEDIFF(DAY, c.FechaRegistroCita, c.FechaProgramada)     AS DiasAnticipacion,
    1                                                         AS CantidadCitas,
    CASE WHEN c.EstadoCitaID = 2 THEN 1 ELSE 0 END            AS Asistidas,
    CASE WHEN c.EstadoCitaID = 3 THEN 1 ELSE 0 END            AS Inasistencias,
    CASE WHEN c.NumeroCita = 2   THEN 1 ELSE 0 END            AS EsSegundaCita
FROM dbo.Citas AS c
JOIN dbo.vw_MapaPaciente AS m ON m.DNI = c.DNI;
GO

-- USO OPERATIVO (no va al cubo): pacientes que no asistieron a su cita y no tienen una nueva.
-- Incluye teléfono sintético para el seguimiento telefónico de segundas citas.
CREATE OR ALTER VIEW dbo.vw_SeguimientoCitas
AS
SELECT
    p.CodigoPaciente,
    p.Nombres,
    p.Apellidos,
    p.TelefonoContacto,
    sv.NombreServicio,
    c.NumeroCita,
    c.MotivoCita,
    c.FechaProgramada,
    DATEDIFF(DAY, c.FechaProgramada, CONVERT(DATE, '20260930', 112)) AS DiasDesdeInasistencia,
    c.RecordatorioEnviado
FROM dbo.Citas AS c
JOIN dbo.Pacientes AS p  ON p.DNI = c.DNI
JOIN dbo.DimServicio AS sv ON sv.ServicioID = c.ServicioID
WHERE c.EstadoCitaID = 3
  AND NOT EXISTS (SELECT 1 FROM dbo.Citas AS n WHERE n.CitaAnteriorID = c.CitaID);
GO

-- 6. CONSULTAS DE VALIDACIÓN.
SELECT N'Atenciones' AS Tabla, COUNT(*) AS Filas FROM dbo.Atenciones   -- 2043
UNION ALL SELECT N'Citas', COUNT(*) FROM dbo.Citas                      -- 579
UNION ALL SELECT N'DiagnosticosAtencion', COUNT(*) FROM dbo.DiagnosticosAtencion  -- 2259
UNION ALL SELECT N'DimDiagnostico', COUNT(*) FROM dbo.DimDiagnostico    -- 44
UNION ALL SELECT N'DimFecha', COUNT(*) FROM dbo.DimFecha;               -- 365

-- Reglas de coherencia: todas deben devolver 0.
SELECT COUNT(*) AS Atencion_antes_del_registro
FROM dbo.Atenciones AS a JOIN dbo.Pacientes AS p ON p.DNI = a.DNI
WHERE a.FechaAtencion < p.FechaRegistro;

SELECT COUNT(*) AS Atencion_con_cita_inconsistente
FROM dbo.Atenciones AS a JOIN dbo.Citas AS c ON c.CitaID = a.CitaID
WHERE c.EstadoCitaID <> 2 OR c.DNI <> a.DNI OR c.FechaProgramada <> a.FechaAtencion
   OR c.ServicioID <> a.ServicioID OR c.ProfesionalID <> a.ProfesionalID;

SELECT COUNT(*) AS Cita_asistida_sin_atencion
FROM dbo.Citas AS c
WHERE c.EstadoCitaID = 2 AND NOT EXISTS (SELECT 1 FROM dbo.Atenciones AS a WHERE a.CitaID = c.CitaID);

SELECT COUNT(*) AS Dx_gestacion_en_varones
FROM dbo.DiagnosticosAtencion AS d
JOIN dbo.DimDiagnostico AS x ON x.DiagnosticoID = d.DiagnosticoID
JOIN dbo.Atenciones AS a ON a.AtencionID = d.AtencionID
JOIN dbo.Pacientes AS p ON p.DNI = a.DNI
WHERE (x.CodigoCIE10 LIKE 'Z34%' OR x.CodigoCIE10 = 'O99.0' OR x.CodigoCIE10 = 'Z30.0') AND p.Sexo = 'M';

SELECT COUNT(*) AS Profesional_con_atenciones_superpuestas
FROM dbo.Atenciones AS a
JOIN dbo.Atenciones AS b
  ON b.ProfesionalID = a.ProfesionalID AND b.FechaAtencion = a.FechaAtencion AND b.AtencionID > a.AtencionID
 AND a.HoraInicio < DATEADD(MINUTE, b.DuracionMin, b.HoraInicio)
 AND b.HoraInicio < DATEADD(MINUTE, a.DuracionMin, a.HoraInicio);

SELECT COUNT(*) AS Atencion_en_domingo_o_feriado
FROM dbo.Atenciones AS a JOIN dbo.DimFecha AS f ON f.Fecha = a.FechaAtencion
WHERE f.EsDiaLaborable = 0;

-- Vistas rápidas para revisar resultados.
SELECT s.NombreServicio, COUNT(*) AS Atenciones, AVG(CAST(a.TiempoEsperaMin AS DECIMAL(6,1))) AS EsperaPromedioMin
FROM dbo.vw_FactAtenciones AS a JOIN dbo.DimServicio AS s ON s.ServicioID = a.ServicioID
GROUP BY s.NombreServicio ORDER BY Atenciones DESC;

SELECT TOP (10) x.CodigoCIE10, x.Descripcion, COUNT(*) AS Casos
FROM dbo.vw_FactDiagnosticos AS f JOIN dbo.DimDiagnostico AS x ON x.DiagnosticoID = f.DiagnosticoID
GROUP BY x.CodigoCIE10, x.Descripcion ORDER BY Casos DESC;

SELECT RecordatorioEnviado,
       COUNT(*) AS CitasCerradas,
       CAST(100.0 * SUM(Asistidas) / COUNT(*) AS DECIMAL(5,1)) AS PctAsistencia
FROM dbo.vw_FactCitas WHERE EstadoCitaID IN (2, 3)
GROUP BY RecordatorioEnviado;

SELECT TOP (10) * FROM dbo.vw_SeguimientoCitas ORDER BY FechaProgramada DESC;
